import { Application } from '@znight/core'

// Generated by the compiler (znight generate, vite build, bun test): every provider, its
// dependencies, the routes and the jobs. Only this file and the tests import it.
import { __ZNIGHT_METADATA__ } from './.znight/container.generated.js'
import { plugins } from './plugins.js'

const app = await Application.create({
  metadata: __ZNIGHT_METADATA__,
  plugins: plugins(),
  // SIGINT / SIGTERM stop the application gracefully, each step bounded by `hookTimeoutMs`:
  // 1. HTTP stops accepting connections, drains in-flight requests and closes the event streams;
  // 2. the scheduler aborts the signal of every running job (`shutdown`) and waits for them, at most
  //    SCHEDULE_DRAIN_TIMEOUT_MS (4 s): a probe's fetch is aborted, the purge returns between batches;
  // 3. providers stop, the database is closed, the logs are flushed.
  // Keep `timeoutMs` below the grace period of your platform (Kubernetes: 30 s, `docker stop`: 10 s).
  shutdown: { timeoutMs: 9_000, hookTimeoutMs: 5_000 },
})

// Jobs start once every provider started and every plugin listens: never against a half-started
// application. While the scheduler runs, it keeps the process alive.
await app.start()
